export function resetPageScroll(lenis) {
  // Lenis 0.2.x ignores scrollTo while stopped, including calls with force:true.
  const stopped = Boolean(lenis?.stopped || lenis?.isStopped);
  if (stopped) lenis.start();
  lenis?.scrollTo(0, { immediate: true, force: true });
  if (stopped) lenis.stop();
  window.scrollTo({ top: 0, left: 0, behavior: "instant" });
}
