export const MAGAZINE_SIZES = {
  s: { artwork: "-2.2rem", inset: "0.4rem" },
  m: { artwork: "-1.1rem", inset: "1.3rem" },
  l: { artwork: "0rem", inset: "2.3rem" },
};

let cleanupCurrent;

export function destroyMagazineLayout() {
  cleanupCurrent?.();
  cleanupCurrent = null;
}

export function initMagazineLayout(root) {
  destroyMagazineLayout();
  if (!document.getElementById("magazine-layout-styles")) {
    const style = document.createElement("style");
    style.id = "magazine-layout-styles";
    style.textContent = `
      .bpage[data-mag-layout] { margin-left: var(--mag-inset); width: calc(100% - var(--mag-inset)) !important; }
      .bpage[data-mag-layout] .hero_logo.main { left: var(--mag-inset); right: 0; width: calc(100% - var(--mag-inset)); }
      .nav_holder { left: var(--mag-inset, 0rem); right: 0; width: calc(100% - var(--mag-inset, 0rem)); }
      .scrolling_banner { left: 0; right: 0; width: 100%; }
      .magazine-edge { position: absolute; overflow: hidden; pointer-events: none; z-index: 20; }
      .magazine-edge img { position: static; inset: auto; display: block; height: auto; max-width: none; margin: 0; }
    `;
    document.head.append(style);
  }
  const pageSize = MAGAZINE_SIZES[root.dataset.mag?.trim().toLowerCase()] || MAGAZINE_SIZES.s;
  let size = window.innerWidth < 991 ? MAGAZINE_SIZES.s : pageSize;
  root.dataset.magLayout = "";
  root.style.setProperty("--mag-inset", size.inset);
  document.documentElement.style.setProperty("--mag-inset", size.inset);
  const edges = [...document.querySelectorAll(".left_mag, .right_mag")]
    .filter((image) => image.tagName === "IMG" && (!image.closest("[data-barba='container']") || root.contains(image)))
    .map((image) => {
      const marker = document.createComment("magazine artwork");
      image.before(marker);
      const wrapper = document.createElement("div");
      wrapper.className = "magazine-edge";
      wrapper.setAttribute("aria-hidden", "true");
      const left = image.classList.contains("left_mag");
      wrapper.style[left ? "left" : "right"] = left ? size.artwork : "0px";
      if (!left) wrapper.style.mixBlendMode = "multiply";
      document.body.append(wrapper);
      wrapper.append(image);
      return { image, marker, wrapper };
    });
  let frame = 0;
  const update = () => {
    frame = 0;
    size = window.innerWidth < 991 ? MAGAZINE_SIZES.s : pageSize;
    root.style.setProperty("--mag-inset", size.inset);
    document.documentElement.style.setProperty("--mag-inset", size.inset);
    const rect = root.getBoundingClientRect();
    for (const { image, wrapper } of edges) {
      if (image.classList.contains("left_mag")) wrapper.style.left = size.artwork;
      if (!image.complete || !image.naturalHeight) continue;
      const width = image.getBoundingClientRect().width;
      const height = width * image.naturalHeight / image.naturalWidth;
      if (!height) continue;
      wrapper.style.top = `${Math.max(0, rect.top + window.scrollY)}px`;
      wrapper.style.height = `${root.scrollHeight}px`;
      wrapper.style.width = `${width}px`;
      const count = Math.max(1, Math.ceil(root.scrollHeight / height));
      while (wrapper.children.length > count) wrapper.lastElementChild.remove();
      while (wrapper.children.length < count) {
        const clone = image.cloneNode(false);
        clone.removeAttribute("id");
        clone.loading = "eager";
        clone.style.transform = wrapper.children.length % 2 ? "scaleY(-1)" : "none";
        wrapper.append(clone);
      }
    }
  };
  const schedule = () => { if (!frame) frame = requestAnimationFrame(update); };
  const observer = new ResizeObserver(schedule);
  observer.observe(root);
  edges.forEach(({ image }) => { image.addEventListener("load", schedule); observer.observe(image); });
  window.addEventListener("resize", schedule);
  schedule();
  cleanupCurrent = () => {
    cancelAnimationFrame(frame);
    observer.disconnect();
    window.removeEventListener("resize", schedule);
    edges.forEach(({ image, marker, wrapper }) => {
      image.removeEventListener("load", schedule);
      marker.replaceWith(image);
      wrapper.remove();
    });
  };
}
