import * as THREE from "three";
import { RoomEnvironment } from "three/examples/jsm/environments/RoomEnvironment.js";
import { HDRLoader } from "three/examples/jsm/loaders/HDRLoader.js";
import { createGeneratedBottle } from "./generated-bottle.js";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { createChampagneCork, CHAMPAGNE_DEFAULTS } from "./champagne-cork.js";

const CORK_MODEL_URL = "https://cdn.jsdelivr.net/gh/kujira22/other-label-texture@73ab4294eccfd67148172d4b68c06465013984d1/models/CorkM3.glb";

const IDLE_DELAY = 1000;
const LOG_PREFIX = "[kujira webgl]";
const STYLE_ID = "kujira-webgl-style";
const DEFAULT_CORK_COLOR = "#b4895d";
const MOBILE_SPIN = { duration: 4.8, speedVariation: 0.78, axisOffset: 0.215, centreBlend: 0.15 };
const labelBaseScales = new WeakMap();

export function initThreeScene({ mount, lenis = null } = {}) {
  if (!mount) {
    console.warn(`${LOG_PREFIX} No [data-three-canvas] mount found.`);
    return null;
  }

  // Webflow exports the mount as a div; Three.js requires a canvas.
  if (mount.tagName !== "CANVAS") {
    const canvas = document.createElement("canvas");
    for (const attribute of mount.attributes) {
      canvas.setAttribute(attribute.name, attribute.value);
    }
    mount.replaceWith(canvas);
    mount = canvas;
  }

  let renderer;

  try {
    renderer = new THREE.WebGLRenderer({ canvas: mount, alpha: true, antialias: true });
  } catch (error) {
    console.warn(`${LOG_PREFIX} Renderer could not be created.`, error);
    return null;
  }

  const settings = getSceneSettings(mount);
  const pageRoot = mount.closest("[data-barba='container']") || document;
  const diagnosticFlags = new URLSearchParams(window.location.search);
  const canvasTestMode = diagnosticFlags.get("canvasTest");
  const staticCanvasTest = canvasTestMode === "static";
  const gsapCanvasYTest = canvasTestMode === "gsapY";
  const canvasYTest = canvasTestMode === "canvasY";
  const userAgent = navigator.userAgent;
  const logoRefractionEnabled = window.innerWidth >= 991 && !(/Safari/i.test(userAgent)
    && !/(Chrome|Chromium|CriOS|Edg|EdgiOS|OPR|FxiOS|Firefox)/i.test(userAgent));
  const useTouchScrollTrigger = window.matchMedia("(hover: none), (pointer: coarse)").matches
    || /Android|iPhone|iPad|iPod/i.test(userAgent)
    || (navigator.maxTouchPoints > 1 && /Macintosh/i.test(userAgent));
  const diagnostics = import.meta.env.DEV || diagnosticFlags.has("diag");
  const scrollTraceEnabled = diagnosticFlags.has("scrollTrace");
  const logDiagnostics = diagnosticFlags.has("diag");
  const diagnosticRenderScale = diagnostics ? Number.parseFloat(diagnosticFlags.get("renderScale")) : NaN;
  const freezeLogoPositionDiagnostic = diagnostics && diagnosticFlags.get("freezeLogoPosition") === "1";
  installWebglStyles();
  const scene = new THREE.Scene();
  const labelOverlayScene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(settings.fov, 1, 0.1, 100);
  const modelGroup = new THREE.Group();
  const spinPivot = new THREE.Group();
  const spinAxis = new THREE.Vector3(0.06, 1, 0.04).normalize();
  const spinContent = new THREE.Group();
  spinPivot.add(spinContent);
  modelGroup.add(spinPivot);
  const timer = new THREE.Timer();
  const hdrLoader = new HDRLoader();
  const pmremGenerator = new THREE.PMREMGenerator(renderer);
  const refractionUniforms = {
    liquidLogoTexture: { value: createEmptyTexture() },
    liquidLogoRect: { value: new THREE.Vector4(0, 0, 1, 1) },
    resolution: { value: new THREE.Vector2(1, 1) },
    logoOffsetY: { value: settings.logoProjectionY },
    logoScrollOffset: { value: 0 },
    backgroundColor: { value: getPageBackgroundColor(mount) },
  };

  camera.position.set(
    settings.cameraPosition.x,
    settings.cameraPosition.y,
    settings.cameraPosition.z,
  );
  camera.lookAt(0, 0, 0);
  const pagePose = { ...settings.pagePoses.home };
  modelGroup.position.set(pagePose.x, pagePose.y, pagePose.z);
  modelGroup.rotation.set(
    THREE.MathUtils.degToRad(pagePose.rx),
    THREE.MathUtils.degToRad(pagePose.ry),
    THREE.MathUtils.degToRad(pagePose.rz),
  );
  let mobileScaleActive = window.matchMedia("(max-width: 767px)").matches;
  modelGroup.scale.setScalar(mobileScaleActive ? settings.mobileModelScale : settings.modelScale);
  if (staticCanvasTest) {
    const heroContainer = document.querySelector("#top, .hero");
    if (heroContainer) heroContainer.insertBefore(mount, heroContainer.firstChild);
    mount.style.cssText = "position:static;display:block;flex:none;width:100vw;height:100svh;max-width:100vw;margin:0 auto;transform:none";
    modelGroup.position.set(0, 0, 0);
    modelGroup.rotation.set(0, 0, 0);
  }
  scene.add(modelGroup);
  scene.add(new THREE.HemisphereLight(0xffffff, 0x555555, 0.7));

  const devicePixelRatio = Math.min(window.devicePixelRatio || 1, 2);
  renderer.setPixelRatio(Number.isFinite(diagnosticRenderScale) && diagnosticRenderScale > 0
    ? Math.min(devicePixelRatio, diagnosticRenderScale)
    : devicePixelRatio);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = getToneMapping(settings.toneMapping);
  renderer.toneMappingExposure = settings.exposure;
  renderer.autoClear = false;
  if (diagnostics) renderer.info.autoReset = false;
  renderer.localClippingEnabled = true;

  const mouseTarget = new THREE.Vector2();
  const mouseRotation = new THREE.Vector2();

  let model = null;
  let generatedBottle = null;
  let generatedLabelSource = null;
  let generatedLabelOverlay = null;
  let frameId = null;
  let idleTimer = null;
  let pagePoseTween = null;
  let logoPlane = null;
  let logoCaptureTimeout = 0;
  let logoCapturePending = false;
  let logoPositionDirty = false;
  let bottleParts = null;
  let physicalBackdrop = null;
  let gui = null;
  let selectPoseInGui = null;
  let updateDiagnosticsInGui = null;
  let running = false;
  let disposed = false;
  let capsulePage = false;
  let scrollPoseEnabled = false;
  let scrollPoseTarget = null;
  let pageInitialized = false;
  let scrollProgress = 0;
  let mobileScrollScrub = null;
  let canvasYScrollTarget = null;
  let diagnosticFrames = 0;
  let diagnosticFrameTime = 0;
  let diagnosticMaxFrameTime = 0;
  let diagnosticWindowStart = performance.now();
  let previousViewportWidth = window.innerWidth;
  let previousCanvasWidth = 0;
  let previousCanvasHeight = 0;
  let mobileScrollDistance = null;
  let spinStarted = performance.now();
  const isMobileCapsule = () => capsulePage && window.innerWidth < 991;
  const originalMountHeight = mount.style.getPropertyValue("height");
  const originalMountHeightPriority = mount.style.getPropertyPriority("height");
  let scrollTracePanel = null;
  let scrollTraceProgress = 0;
  let scrollTraceScroll = window.scrollY;
  let scrollTraceLastUpdate = 0;
  let scrollTraceLastFrame = 0;
  let scrollTraceMaxFrameGap = 0;
  let scrollTraceFrameCount = 0;
  let scrollTraceFrameGapTotal = 0;
  let scrollTraceFps = 0;
  let scrollTraceAverageGap = 0;
  let scrollTraceWindowStart = performance.now();
  let scrollTraceUiUpdate = 0;

  const ready = Promise.all([setupEnvironment(), loadLogoPlane(), loadModel()]);

  function getWidth() {
    return mount.clientWidth || window.innerWidth || 1;
  }

  function getHeight() {
    return mount.clientHeight || window.innerHeight || 1;
  }

  function resize() {
    if (disposed) return;
    const viewportWidth = window.innerWidth;
    const mobileCapsule = /capsule\s*02/i.test(pageRoot.dataset?.barbaNamespace || "") && viewportWidth < 991;
    if (bottleParts && (viewportWidth < 991) !== (previousViewportWidth < 991)) {
      bottleParts.physicalGlassMaterial.transmission = viewportWidth < 991 ? 0 : 1;
      bottleParts.physicalGlassMaterial.dispersion = viewportWidth < 991 ? 0 : 0.68;
      bottleParts.physicalGlassMaterial.needsUpdate = true;
    }
    if (mobileCapsule) {
      if (!previousCanvasHeight || viewportWidth !== previousViewportWidth) {
        mount.style.removeProperty("height");
        mount.style.setProperty("height", `${getHeight()}px`, "important");
        mobileScrollDistance = null;
      }
    } else {
      if (originalMountHeight) mount.style.setProperty("height", originalMountHeight, originalMountHeightPriority);
      else mount.style.removeProperty("height");
      mobileScrollDistance = null;
    }
    const useMobileScale = window.matchMedia("(max-width: 767px)").matches;
    if (useMobileScale !== mobileScaleActive) {
      mobileScaleActive = useMobileScale;
      modelGroup.scale.setScalar(useMobileScale ? settings.mobileModelScale : settings.modelScale);
    }
    const width = getWidth();
    const height = getHeight();
    if (width === previousCanvasWidth && height === previousCanvasHeight && viewportWidth === previousViewportWidth) return;
    previousViewportWidth = viewportWidth;
    previousCanvasWidth = width;
    previousCanvasHeight = height;

    camera.aspect = width / height;
    camera.updateProjectionMatrix();
    renderer.setSize(width, height, false);
    renderer.getDrawingBufferSize(refractionUniforms.resolution.value);
    if (logoPlane) {
      logoPlane.userData.logoRect = null;
      logoPlane.userData.logoRectKey = null;
      logoPositionDirty = true;
    }
    physicalBackdrop?.update(logoPlane?.userData?.logoTexture?.image, refractionUniforms.backgroundColor.value);
    const poses = settings.poseSets[viewportWidth < 991 ? "below991" : "from991"];
    if (settings.pagePoses !== poses) {
      settings.pagePoses = poses;
      setPage({ capsule: capsulePage, scrollTarget: scrollPoseTarget });
    }
    if (capsulePage || scrollPoseEnabled) syncScroll();
    requestLogoTextureUpdate();
    wake("resize");
  }

  function requestLogoTextureUpdate() {
    if (!logoPlane || disposed) return;
    logoCapturePending = true;
    if (logoPlane.userData.updating || logoCaptureTimeout) return;
    const delay = Math.max(0, 1000 / settings.logoCaptureFps - (performance.now() - logoPlane.userData.lastTextureUpdate));
    logoCaptureTimeout = window.setTimeout(() => {
      logoCaptureTimeout = 0;
      updateLogoTexture();
    }, delay);
  }

  async function updateLogoTexture() {
    if (!logoCapturePending || !logoPlane || disposed) return;
    logoCapturePending = false;

    const source = logoPlane.userData.logoElement.querySelector("svg, img[data-static-hero-logo]");
    const texture = logoPlane.userData.logoTexture;
    const canvas = texture.image;
    const context = logoPlane.userData.logoContext;

    if (!source || !context) return;
    logoPlane.userData.updating = true;
    logoPlane.userData.lastTextureUpdate = performance.now();
    try {
      const image = await drawLogoToCanvas(source, logoPlane.userData.logoElement, mount, canvas, context, settings);
      if (!disposed) {
        logoPlane.userData.logoImage = image;
        logoPlane.userData.logoRectKey = getLogoRectKey(logoPlane.userData.logoElement, mount, settings);
        logoPlane.userData.logoRect = getLogoPixelRect(logoPlane.userData.logoElement, mount, settings);
        refractionUniforms.logoScrollOffset.value = 0;
        if (bottleParts?.liquidLogoStrength.value > 0) logoPlane.userData.liquidLogo.updateImage(image);
        texture.needsUpdate = true;
        physicalBackdrop?.setVerticalOffset(0);
        physicalBackdrop?.update(canvas, refractionUniforms.backgroundColor.value);
        wake("logo texture updated");
      }
    } catch (error) {
      console.warn(`${LOG_PREFIX} Logo capture failed.`, error);
    } finally {
      logoPlane.userData.updating = false;
      if (logoCapturePending) requestLogoTextureUpdate();
    }
  }

  function updateLogoPosition() {
    if (freezeLogoPositionDiagnostic) {
      logoPositionDirty = false;
      return;
    }
    if (!logoPlane?.userData.logoImage || logoPlane.userData.updating) return;
    logoPositionDirty = false;
    const { logoElement, logoImage, logoTexture, logoContext } = logoPlane.userData;
    const rect = getLogoPixelRect(logoElement, mount, settings);
    const rectKey = `${rect.x},${rect.y},${rect.width},${rect.height}`;
    if (rectKey === logoPlane.userData.logoRectKey) return;
    resizeLogoCanvas(logoTexture.image, mount, settings);
    drawLogoImage(logoImage, logoElement, mount, logoTexture.image, logoContext, settings);
    logoPlane.userData.logoRect = rect;
    logoPlane.userData.logoRectKey = rectKey;
    logoTexture.needsUpdate = true;
    if (bottleParts?.liquidLogoStrength.value > 0) logoPlane.userData.liquidLogo.position();
    refractionUniforms.logoScrollOffset.value = 0;
    physicalBackdrop?.setVerticalOffset(0);
    physicalBackdrop?.update(logoTexture.image, refractionUniforms.backgroundColor.value);
  }

  function render() {
    if (!running) return;
    const frameStart = diagnostics ? performance.now() : 0;
    const frameNow = performance.now();
    if (scrollTraceLastFrame) {
      const frameGap = frameNow - scrollTraceLastFrame;
      scrollTraceMaxFrameGap = Math.max(scrollTraceMaxFrameGap, frameGap);
      scrollTraceFrameGapTotal += frameGap;
      scrollTraceFrameCount += 1;
    }
    scrollTraceLastFrame = frameNow;
    if (scrollTraceEnabled && frameNow - scrollTraceWindowStart >= 1000) {
      const elapsed = frameNow - scrollTraceWindowStart;
      scrollTraceFps = Math.round(scrollTraceFrameCount * 1000 / elapsed);
      scrollTraceAverageGap = scrollTraceFrameCount ? scrollTraceFrameGapTotal / scrollTraceFrameCount : 0;
      scrollTraceFrameCount = 0;
      scrollTraceFrameGapTotal = 0;
      scrollTraceWindowStart = frameNow;
    }
    timer.update();
    if (logoPositionDirty) updateLogoPosition();
    const delta = Math.min(timer.getDelta(), 0.1);

    if (model) {
      model.rotation.x += settings.intrinsicRotationSpeed.x * delta;
      model.rotation.y += settings.intrinsicRotationSpeed.y * delta;
    }

    mouseRotation.x = THREE.MathUtils.damp(mouseRotation.x, mouseTarget.x, 7, delta);
    mouseRotation.y = THREE.MathUtils.damp(mouseRotation.y, mouseTarget.y, 7, delta);
    const radius = settings.cameraPosition.z;
    camera.position.set(
      radius * Math.sin(mouseRotation.x) * Math.cos(mouseRotation.y),
      radius * Math.sin(mouseRotation.y),
      radius * Math.cos(mouseRotation.x) * Math.cos(mouseRotation.y),
    );
    camera.lookAt(0, 0, 0);
    physicalBackdrop?.position(camera);
    if (isMobileCapsule()) {
      Object.assign(pagePose, settings.pagePoses.home);
      const phase = ((frameNow - spinStarted) / 1000 / MOBILE_SPIN.duration) % 1;
      // Linger through the slow portion without ever stopping the rotation.
      const warpedPhase = phase - 0.10 * Math.sin(phase * Math.PI * 2);
      const angle = warpedPhase * Math.PI * 2;
      // Continuous positive speed: slow at each end, fast through the middle.
      spinPivot.quaternion.setFromAxisAngle(spinAxis, angle - MOBILE_SPIN.speedVariation * Math.sin(angle));
      pagePose.rx -= 4;
    } else if (scrollPoseEnabled && !mobileScrollScrub) {
      const { home, capsule } = settings.pagePoses;
      for (const key of ["x", "y", "z", "rx", "ry", "rz"]) {
        pagePose[key] = THREE.MathUtils.lerp(home[key], capsule[key], scrollProgress);
      }
    }
    if (!isMobileCapsule()) {
      spinPivot.quaternion.identity();
    }
    if (!mobileScrollScrub) {
      modelGroup.position.set(
        pagePose.x,
        pagePose.y,
        pagePose.z,
      );
      modelGroup.rotation.set(
        THREE.MathUtils.degToRad(pagePose.rx),
        THREE.MathUtils.degToRad(pagePose.ry),
        THREE.MathUtils.degToRad(pagePose.rz),
      );
    }
    if (generatedBottle?.root.visible) generatedBottle.updateHorizontalLevel();
    updateScrollTrace(frameNow);
    const showLabelOverlay = Boolean(generatedLabelSource?.visible && generatedBottle?.root.visible);
    if (generatedLabelSource) generatedLabelSource.visible = false;
    renderer.clear();
    renderer.render(scene, camera);
    if (generatedLabelSource) generatedLabelSource.visible = showLabelOverlay;
    if (generatedLabelSource && generatedLabelOverlay && showLabelOverlay) {
      generatedBottle.root.updateWorldMatrix(true, true);
      generatedLabelOverlay.matrix.copy(generatedLabelSource.matrixWorld);
      generatedLabelOverlay.matrixWorldNeedsUpdate = true;
      generatedLabelOverlay.visible = true;
      renderer.clearDepth();
      renderer.render(labelOverlayScene, camera);
    } else if (generatedLabelOverlay) {
      generatedLabelOverlay.visible = false;
    }
    if (diagnostics) {
      const now = performance.now();
      const frameTime = now - frameStart;
      diagnosticFrames += 1;
      diagnosticFrameTime += frameTime;
      diagnosticMaxFrameTime = Math.max(diagnosticMaxFrameTime, frameTime);
      if (now - diagnosticWindowStart >= 1000) {
        const seconds = (now - diagnosticWindowStart) / 1000;
        const stats = {
          fps: Math.round(diagnosticFrames / seconds),
          averageFrameMs: Number((diagnosticFrameTime / diagnosticFrames).toFixed(2)),
          maxFrameMs: Number(diagnosticMaxFrameTime.toFixed(2)),
          drawCallsPerFrame: Number((renderer.info.render.calls / diagnosticFrames).toFixed(1)),
          trianglesPerFrame: Math.round(renderer.info.render.triangles / diagnosticFrames),
          geometries: renderer.info.memory.geometries,
          textures: renderer.info.memory.textures,
        };
        updateDiagnosticsInGui?.(stats);
        if (logDiagnostics) console.info("[webgl diagnostics]", stats);
        renderer.info.reset();
        diagnosticFrames = 0;
        diagnosticFrameTime = 0;
        diagnosticMaxFrameTime = 0;
        diagnosticWindowStart = now;
      }
    }
    frameId = window.requestAnimationFrame(render);
  }

  function start(reason) {
    if (running || document.hidden || disposed) return;

    running = true;
    updateDiagnosticsInGui?.({ state: "Rendering" });
    timer.update();
    console.log(`${LOG_PREFIX} rendering started`, { reason });
    render();
  }

  function stop(reason) {
    if (!running) return;
    if (reason === "idle" && isMobileCapsule() && window.scrollY < getHeight() * 1.3) return;

    running = false;
    window.cancelAnimationFrame(frameId);
    frameId = null;
    updateDiagnosticsInGui?.({ state: "Idle" });
    console.log(`${LOG_PREFIX} rendering stopped`, { reason });
  }

  function wake(reason = "activity", delay = IDLE_DELAY) {
    window.clearTimeout(idleTimer);
    start(reason);
    idleTimer = window.setTimeout(() => stop("idle"), delay);
  }

  function handleActivity(event) {
    if (event.type === "pointermove" && event.pointerType === "mouse") {
      mouseTarget.x = ((event.clientX / window.innerWidth) * 2 - 1) * settings.mouseYawRange;
      mouseTarget.y = (1 - (event.clientY / window.innerHeight) * 2) * settings.mousePitchRange;
    }
    if (event.type === "scroll") {
      syncScroll();
      return;
    }
    wake(event.type);
  }

  function getMobileScrollDistance() {
    return mobileScrollDistance ??= Math.max(document.documentElement.scrollHeight - getHeight(), 1);
  }

  function syncScroll(scroll = lenis?.scroll ?? window.scrollY, limit = lenis?.limit) {
    if (pageRoot.dataset?.pageLeaving) return;
    scrollTraceScroll = scroll;
    scrollTraceLastUpdate = performance.now();
    if (!mobileScrollScrub) {
      const mobileCapsule = capsulePage && window.innerWidth < 991;
      if (mobileCapsule) scroll = window.scrollY;
      const distance = Math.max(mobileCapsule
        ? getMobileScrollDistance()
        : limit ?? document.documentElement.scrollHeight - window.innerHeight, 1);
      const targetTop = scrollPoseTarget && !(capsulePage && window.innerWidth < 991)
        ? scrollPoseTarget.getBoundingClientRect().top + scroll
        : distance;
      scrollProgress = capsulePage || scrollPoseEnabled
        ? THREE.MathUtils.clamp(scroll / Math.max(targetTop, 1), 0, 1)
        : 0;
      scrollTraceProgress = scrollProgress;
    }
    selectPoseInGui?.(scrollPoseEnabled ? (scrollProgress >= 0.5 ? "capsule" : "home") : (capsulePage ? "capsule" : "home"));
    logoPositionDirty = logoRefractionEnabled;
    wake("scroll position");
  }

  function updateCanvasYFromNativeScroll() {
    if (!canvasYTest || !canvasYScrollTarget) return;
    const scroll = window.scrollY;
    const targetTop = canvasYScrollTarget.getBoundingClientRect().top + scroll;
    const progress = THREE.MathUtils.clamp(scroll / Math.max(targetTop, 1), 0, 1);
    mount.style.setProperty("transform", `translate3d(0, ${window.innerHeight * 0.5 * progress}px, 0)`, "important");
    scrollTraceScroll = scroll;
    scrollTraceLastUpdate = performance.now();
    wake("native canvas Y scroll");
  }

  function updateMobileScrollProgress(self) {
    if (!self) return;
    scrollProgress = THREE.MathUtils.clamp(self.progress, 0, 1);
    scrollTraceProgress = scrollProgress;
    pagePose.x = modelGroup.position.x;
    pagePose.y = modelGroup.position.y;
    pagePose.z = modelGroup.position.z;
    pagePose.rx = THREE.MathUtils.radToDeg(modelGroup.rotation.x);
    pagePose.ry = THREE.MathUtils.radToDeg(modelGroup.rotation.y);
    pagePose.rz = THREE.MathUtils.radToDeg(modelGroup.rotation.z);
    selectPoseInGui?.(scrollPoseEnabled ? (scrollProgress >= 0.5 ? "capsule" : "home") : (capsulePage ? "capsule" : "home"));
    logoPositionDirty = logoRefractionEnabled;
    wake("scroll scrub");
  }

  function updateScrollTrace(now) {
    if (!scrollTracePanel || now - scrollTraceUiUpdate < 100) return;
    scrollTraceUiUpdate = now;
    const rect = renderer.domElement.getBoundingClientRect();
    const scrollAge = scrollTraceLastUpdate ? Math.round(now - scrollTraceLastUpdate) : "-";
    scrollTracePanel.textContent = [
      `scrollY ${Math.round(scrollTraceScroll)} | lenis ${Math.round(lenis?.scroll ?? -1)}`,
      `ScrollTrigger ${scrollTraceProgress.toFixed(3)} | input age ${scrollAge}ms`,
      `group y ${modelGroup.position.y.toFixed(3)} | rotation ${modelGroup.rotation.x.toFixed(2)}, ${modelGroup.rotation.y.toFixed(2)}, ${modelGroup.rotation.z.toFixed(2)}`,
      `RAF ${scrollTraceFps}fps avg ${scrollTraceAverageGap.toFixed(1)}ms | max gap ${scrollTraceMaxFrameGap.toFixed(1)}ms`,
      `canvas ${Math.round(rect.width)}x${Math.round(rect.height)} @ ${Math.round(rect.top)} | DPR ${renderer.getPixelRatio().toFixed(2)}`,
    ].join("\n");
    scrollTraceMaxFrameGap = 0;
  }

  function createScrollTracePanel() {
    if (!scrollTraceEnabled) return;
    scrollTracePanel = document.createElement("pre");
    scrollTracePanel.style.cssText = "position:fixed;z-index:2147483647;left:8px;bottom:8px;margin:0;padding:8px;background:rgba(0,0,0,.82);color:#8ff;font:11px/1.4 monospace;white-space:pre;pointer-events:none";
    scrollTracePanel.textContent = "Waiting for first render";
    document.body.appendChild(scrollTracePanel);
  }

  function setPage({ capsule = false, scrollTarget = null } = {}) {
    mobileScrollScrub?.scrollTrigger?.kill();
    mobileScrollScrub?.kill();
    mobileScrollScrub = null;
    if (!canvasYTest) mount.style.removeProperty("transform");
    if (staticCanvasTest) {
      capsulePage = false;
      scrollPoseEnabled = false;
      scrollPoseTarget = null;
      scrollProgress = 0;
      scrollTraceProgress = 0;
      Object.assign(pagePose, { x: 0, y: 0, z: 0, rx: 0, ry: 0, rz: 0 });
      modelGroup.position.set(0, 0, 0);
      modelGroup.rotation.set(0, 0, 0);
      pageInitialized = true;
      syncScroll();
      return;
    }
    if (canvasYTest && scrollTarget) {
      capsulePage = false;
      scrollPoseEnabled = false;
      scrollPoseTarget = null;
      canvasYScrollTarget = scrollTarget;
      scrollProgress = 0;
      scrollTraceProgress = 0;
      Object.assign(pagePose, { x: 0, y: 0, z: 0, rx: 0, ry: 0, rz: 0 });
      modelGroup.position.set(0, 0, 0);
      modelGroup.rotation.set(0, 0, 0);
      pageInitialized = true;
      updateCanvasYFromNativeScroll();
      syncScroll();
      return;
    }
    canvasYScrollTarget = null;
    if (gsapCanvasYTest && window.gsap && window.ScrollTrigger && scrollTarget) {
      capsulePage = false;
      scrollPoseEnabled = false;
      scrollPoseTarget = null;
      const home = settings.pagePoses.home;
      modelGroup.position.set(home.x, home.y, home.z);
      modelGroup.rotation.set(
        THREE.MathUtils.degToRad(home.rx),
        THREE.MathUtils.degToRad(home.ry),
        THREE.MathUtils.degToRad(home.rz),
      );
      mobileScrollScrub = window.gsap.timeline({
        onUpdate: () => updateMobileScrollProgress(mobileScrollScrub?.scrollTrigger),
        scrollTrigger: {
          trigger: scrollTarget,
          start: 0,
          end: () => Math.max(scrollTarget.getBoundingClientRect().top + window.scrollY, 1),
          scrub: 0,
          invalidateOnRefresh: true,
        },
      });
      mobileScrollScrub.to(modelGroup.position, {
        y: settings.pagePoses.capsule.y,
        ease: "none",
      }, 0);
      mobileScrollScrub.to(modelGroup.rotation, {
        x: THREE.MathUtils.degToRad(home.rx - 90),
        y: THREE.MathUtils.degToRad(home.ry + 180),
        z: THREE.MathUtils.degToRad(home.rz + 90),
        ease: "none",
      }, 0);
      mobileScrollScrub.scrollTrigger?.refresh();
      pageInitialized = true;
      syncScroll();
      return;
    }
    capsulePage = capsule;
    const rotateOnlyMobile = capsule && window.innerWidth < 991;
    scrollPoseEnabled = Boolean(scrollTarget);
    scrollPoseTarget = scrollTarget;
    const target = settings.pagePoses[capsule ? "capsule" : "home"];
    pagePoseTween?.kill();
    if (rotateOnlyMobile) {
      Object.assign(pagePose, settings.pagePoses.home);
    } else if (scrollPoseEnabled) {
      Object.assign(pagePose, settings.pagePoses.home);
      scrollProgress = 0;
      if (useTouchScrollTrigger && window.gsap && window.ScrollTrigger) {
        const { home, capsule } = settings.pagePoses;
        modelGroup.position.set(home.x, home.y, home.z);
        modelGroup.rotation.set(
          THREE.MathUtils.degToRad(home.rx),
          THREE.MathUtils.degToRad(home.ry),
          THREE.MathUtils.degToRad(home.rz),
        );
        mobileScrollScrub = window.gsap.timeline({
          onUpdate: () => updateMobileScrollProgress(mobileScrollScrub?.scrollTrigger),
          scrollTrigger: {
            trigger: scrollPoseTarget,
            start: 0,
            end: () => Math.max(scrollPoseTarget.getBoundingClientRect().top + window.scrollY, 1),
            scrub: 0,
            invalidateOnRefresh: true,
          },
        });
        mobileScrollScrub.to(modelGroup.position, {
          x: capsule.x,
          y: capsule.y,
          z: capsule.z,
          ease: "none",
        }, 0);
        mobileScrollScrub.to(modelGroup.rotation, {
          x: THREE.MathUtils.degToRad(capsule.rx),
          y: THREE.MathUtils.degToRad(capsule.ry),
          z: THREE.MathUtils.degToRad(capsule.rz),
          ease: "none",
        }, 0);
        mobileScrollScrub.scrollTrigger?.refresh();
      }
    } else if (pageInitialized && window.gsap) {
      pagePoseTween = window.gsap.to(pagePose, {
        ...target,
        duration: 0.7,
        ease: "power2.inOut",
        onUpdate: () => wake("page pose"),
      });
    } else {
      Object.assign(pagePose, target);
    }
    pageInitialized = true;
    syncScroll();
  }

  function onLenisScroll({ scroll, limit }) {
    syncScroll(scroll, limit);
  }

  function handleVisibilityChange() {
    if (document.hidden) {
      window.clearTimeout(idleTimer);
      stop("tab hidden");
      return;
    }

    wake("tab visible");
  }

  async function loadModel() {
    try {
      const generated = createGeneratedBottle();
      let champagneCork = null;
      const namespace = pageRoot.dataset?.barbaNamespace?.trim().toLowerCase();
      if (namespace === "capsule 02" || namespace === "capsule02") {
        try {
          const gltf = await new GLTFLoader().loadAsync(CORK_MODEL_URL);
          if (disposed) {
            disposeModel(gltf.scene);
            disposeModel(generated.root);
            return;
          }
          champagneCork = createChampagneCork(gltf.scene, generated.cork);
        } catch (error) {
          console.warn(`${LOG_PREFIX} Champagne cork unavailable; using generated cork.`, error);
        }
      }
      bottleParts = createGeneratedMaterials(refractionUniforms, logoRefractionEnabled, window.innerWidth < 991);
      if (diagnostics && window.innerWidth >= 991) {
        const transmission = Number.parseFloat(diagnosticFlags.get("glassTransmission"));
        const dispersion = Number.parseFloat(diagnosticFlags.get("glassDispersion"));
        if (Number.isFinite(transmission)) bottleParts.physicalGlassMaterial.transmission = THREE.MathUtils.clamp(transmission, 0, 1);
        if (Number.isFinite(dispersion)) bottleParts.physicalGlassMaterial.dispersion = THREE.MathUtils.clamp(dispersion, 0, 1);
      }
      if (disposed) {
        disposeModel(generated.root);
        return;
      }
      try {
        generated.labelArea.material.map = await loadLabelTexture("https://cdn.jsdelivr.net/gh/kujira22/other-label-texture@main/label.png");
        generated.labelArea.material.needsUpdate = true;
      } catch (error) {
        console.warn(`${LOG_PREFIX} Label texture could not be loaded.`, error);
      }
      if (disposed) {
        disposeModel(generated.root);
        if (champagneCork) disposeModel(champagneCork.mesh);
        return;
      }
      generatedLabelSource = generated.labelArea;
      generatedLabelOverlay = generated.labelArea.clone();
      generatedLabelOverlay.matrixAutoUpdate = false;
      generatedLabelOverlay.renderOrder = 0;
      generatedLabelSource.visible = false;
      labelOverlayScene.add(generatedLabelOverlay);
      generatedBottle = generated;
      frameModel(generated.root);
      const corkHolder = new THREE.Group();
      corkHolder.name = "Cork options";
      generated.root.add(corkHolder);
      corkHolder.add(generated.cork);
      const setCorkType = (type) => {
        generated.cork.visible = type !== "champagne" || !champagneCork;
        if (champagneCork) champagneCork.mesh.visible = type === "champagne";
      };
      if (champagneCork) {
        corkHolder.add(champagneCork.mesh);
      }
      setCorkType(champagneCork ? "champagne" : "simple");
      generated.glass.material = bottleParts.physicalGlassMaterial;
      generated.baseDetails.children.forEach((mesh) => { mesh.material = bottleParts.physicalGlassMaterial; });
      generated.liquid.material = bottleParts.liquidMaterial;
      const liquidCapMaterial = bottleParts.liquidMaterial.clone();
      liquidCapMaterial.onBeforeCompile = bottleParts.liquidMaterial.onBeforeCompile;
      liquidCapMaterial.customProgramCacheKey = bottleParts.liquidMaterial.customProgramCacheKey.bind(bottleParts.liquidMaterial);
      generated.liquidCap.material = liquidCapMaterial;
      bottleParts.liquidMaterial.clippingPlanes = [generated.clippingPlane];
      bottleParts.glassMeshes = [generated.glass, ...generated.baseDetails.children];
      bottleParts.liquidMeshes = [generated.liquid, generated.liquidCap];
      bottleParts.labelMeshes = [generated.labelArea];
      bottleParts.corkMeshes = [corkHolder];
      generated.root.visible = true;
      // Bias the axis towards the previous group origin for a wider orbit.
      const bodyBounds = new THREE.Box3().setFromObject(generated.glass);
      bodyBounds.getCenter(spinPivot.position);
      spinPivot.position.x += MOBILE_SPIN.axisOffset;
      spinPivot.position.multiplyScalar(MOBILE_SPIN.centreBlend);
      spinContent.position.copy(spinPivot.position).negate();
      spinContent.add(generated.root);
      spinStarted = performance.now();
      model = generated.root;
      if (diagnostics) {
        generated.updateHorizontalLevel();
        const geometryInventory = [];
        generated.root.traverse((object) => {
          if (!object.isMesh) return;
          const geometry = object.geometry;
          const triangles = (geometry.index?.count ?? geometry.getAttribute("position")?.count ?? 0) / 3;
          geometryInventory.push({
            name: object.name,
            triangles: Math.round(triangles * (object.isInstancedMesh ? object.count : 1)),
          });
        });
        window.__webglGeometryInventory = geometryInventory;
        console.info("[webgl geometry]", geometryInventory);
      }
      const setCorkColor = (color) => generated.cork.material.color.set(color);
      setCorkColor(DEFAULT_CORK_COLOR);
      setMeshesVisible(bottleParts.glassMeshes, true);
      setMeshesVisible(bottleParts.liquidMeshes, true);
      setMeshesVisible(bottleParts.labelMeshes, true);
      setMeshesVisible(bottleParts.corkMeshes, true);
      if (import.meta.env.DEV) {
        const debugGui = await createDebugGui({
          bottleParts,
          modelGroup,
          refractionUniforms,
          setLabelScale,
          settings,
          wake,
          pagePose,
          isCapsulePage: () => capsulePage,
          isScrollPoseEnabled: () => scrollPoseEnabled,
          stopPageTween: () => pagePoseTween?.kill(),
          setGeneratedLiquidLevel: generated.setLiquidLevel,
          generatedLiquidLevel: generated.liquidLevel,
          liquidCapMaterial,
          corkColor: DEFAULT_CORK_COLOR,
          setCorkColor,
          setCorkLength: generated.setCorkLength,
          setCorkThickness: generated.setCorkThickness,
          setCorkType: champagneCork ? setCorkType : null,
          setCorkScale: champagneCork?.setScale,
          setCorkRotation: champagneCork?.setRotation,
          champagneMaterials: champagneCork?.materials,
          setCorkYOffset: champagneCork?.setYOffset,
          refreshLiquidLogo: () => {
            if (logoPlane?.userData.logoImage) logoPlane.userData.liquidLogo.updateImage(logoPlane.userData.logoImage);
          },
        });
        gui = debugGui.gui;
        selectPoseInGui = debugGui.selectPose;
        updateDiagnosticsInGui = debugGui.updateDiagnostics;
        selectPoseInGui(scrollPoseEnabled && scrollProgress >= 0.5 ? "capsule" : (capsulePage ? "capsule" : "home"));
      }
      wake("model loaded");
    } catch (error) {
      console.warn(`${LOG_PREFIX} Generated bottle could not be created.`, error);
    }
  }

  async function loadLogoPlane() {
    if (!logoRefractionEnabled) return;
    const logoElement = pageRoot.querySelector(settings.logoSelector);
    if (!logoElement) return;

    const source = await waitForLogoSource(logoElement);
    if (!source || disposed) return;

    try {
      const texture = await createLogoTexture(source, logoElement, mount, settings);

      const liquidLogo = createLiquidLogoTexture(texture.userData.logoImage, logoElement, mount, settings, bottleParts?.liquidMaterial.roughness ?? 1, refractionUniforms.liquidLogoRect.value);
      refractionUniforms.liquidLogoTexture.value = liquidLogo.texture;
      physicalBackdrop = createPhysicalBackdrop(scene);
      physicalBackdrop.update(texture.image, refractionUniforms.backgroundColor.value);
      logoPlane = {
        userData: {
          logoElement,
          logoTexture: texture,
          logoContext: texture.image.getContext("2d"),
          logoImage: texture.userData.logoImage,
          logoRectKey: getLogoRectKey(logoElement, mount, settings),
          logoRect: getLogoPixelRect(logoElement, mount, settings),
          liquidLogo,
          lastTextureUpdate: performance.now(),
        },
      };
      logoElement.style.opacity = settings.domLogoOpacity;
      requestLogoTextureUpdate();
      wake("logo texture loaded");
    } catch (error) {
      console.warn(`${LOG_PREFIX} Logo texture could not be created.`, error);
    }
  }

  function setLabelScale(meshes, scale = 1) {
    meshes.forEach((mesh) => {
      if (!labelBaseScales.has(mesh)) labelBaseScales.set(mesh, mesh.scale.clone());
      const base = labelBaseScales.get(mesh);
      mesh.scale.set(base.x * scale, base.y, base.z * scale);
    });
  }

  async function setupEnvironment() {
    const hdriUrl = mount.dataset.threeHdri;

    if (hdriUrl) {
      try {
        const texture = await hdrLoader.loadAsync(hdriUrl);
        const environment = pmremGenerator.fromEquirectangular(texture).texture;
        texture.dispose();
        scene.environment = environment;
        if (settings.showEnvironment) scene.background = environment;
        return;
      } catch (error) {
        console.warn(`${LOG_PREFIX} HDRI could not be loaded; using preset environment.`, error);
      }
    }

    const environment = pmremGenerator.fromScene(
      new RoomEnvironment(),
      getEnvironmentBlur(settings.environment),
    ).texture;
    scene.environment = environment;
  }

  function destroy() {
    window.removeEventListener("resize", resize);
    canvasResizeObserver.disconnect();
    if (originalMountHeight) mount.style.setProperty("height", originalMountHeight, originalMountHeightPriority);
    else mount.style.removeProperty("height");
    window.removeEventListener("pointermove", handleActivity);
    window.removeEventListener("scroll", updateCanvasYFromNativeScroll);
    if (lenis) lenis.off?.("scroll", onLenisScroll);
    else window.removeEventListener("scroll", handleActivity);
    document.removeEventListener("visibilitychange", handleVisibilityChange);
    pageRoot.querySelector(settings.logoSelector)?.removeEventListener("logo-frame-change", requestLogoTextureUpdate);
    scrollTracePanel?.remove();
    window.clearTimeout(idleTimer);
    window.clearTimeout(logoCaptureTimeout);
    pagePoseTween?.kill();
    mobileScrollScrub?.scrollTrigger?.kill();
    mobileScrollScrub?.kill();
    stop("destroy");
    disposed = true;

    if (generatedBottle) disposeModel(generatedBottle.root);
    physicalBackdrop?.dispose();
    if (logoPlane?.userData?.logoElement) logoPlane.userData.logoElement.style.opacity = String(settings.domLogoOpacity);
    logoPlane?.userData?.logoTexture?.dispose?.();
    logoPlane?.userData?.liquidLogo?.dispose();
    gui?.destroy();
    pmremGenerator.dispose();
    scene.environment?.dispose?.();
    renderer.dispose();
    renderer.domElement.remove();
  }

  const canvasResizeObserver = new ResizeObserver(resize);
  canvasResizeObserver.observe(mount);
  window.addEventListener("resize", resize);
  if (logoRefractionEnabled) {
    pageRoot.querySelector(settings.logoSelector)?.addEventListener("logo-frame-change", requestLogoTextureUpdate);
  }
  window.addEventListener("pointermove", handleActivity, { passive: true });
  if (canvasYTest) window.addEventListener("scroll", updateCanvasYFromNativeScroll, { passive: true });
  if (lenis) lenis.on("scroll", onLenisScroll);
  else window.addEventListener("scroll", handleActivity, { passive: true });
  document.addEventListener("visibilitychange", handleVisibilityChange);
  resize();
  createScrollTracePanel();

  return { ready, setPage, syncScroll, destroy };
}

