let pageBodyClasses;

export function getPageElement(root, selector) {
  return root.querySelector(selector) || [...document.querySelectorAll(selector)]
    .find((element) => !element.closest("[data-barba='container']")) || null;
}

export function syncPageShell(root, incoming, beforeRemove = () => {}) {
  pageBodyClasses ??= [...document.body.classList];
  if (incoming === document) return;
  pageBodyClasses.forEach((name) => document.body.classList.remove(name));
  pageBodyClasses = [...incoming.body.classList];
  pageBodyClasses.forEach((name) => document.body.classList.add(name));

  for (const selector of [".nav_holder", ".scrolling_banner", ".left_mag", ".right_mag"]) {
    const existing = [...document.querySelectorAll(selector)]
      .filter((element) => !element.closest("[data-barba='container']"));
    const next = [...incoming.querySelectorAll(selector)]
      .find((element) => !element.closest("[data-barba='container']"));
    const replacement = next ? document.importNode(next, true) : null;
    existing.forEach((element, index) => {
      beforeRemove(element);
      if (index === 0 && replacement) element.replaceWith(replacement);
      else element.remove();
    });
    if (replacement && !existing.length) root.before(replacement);
  }
}
