export function initPlayVideo(root) {
  const videos = [];
  let destroyed = false;

  root.querySelectorAll("[data-video-on-hover]").forEach((wrapper) => {
    const video = wrapper.querySelector("video");
    const src = wrapper.getAttribute("data-video-src");
    if (!video || !src) return;

    video.muted = true;
    video.autoplay = true;
    video.playsInline = true;
    if (video.getAttribute("src") !== src) video.setAttribute("src", src);
    wrapper.dataset.videoOnHover = "active";
    videos.push(video);

    video.play().catch((error) => {
      if (!destroyed) console.warn("Autoplay was blocked:", error);
    });
  });

  return () => {
    destroyed = true;
    videos.forEach((video) => video.pause());
  };
}
