import { getPageElement } from "./page-shell.js";

let bannerDismissed = false;
let retainedGradientProgress = 0;

export function initShopPageUi({ root, lenis }) {
  const nav = getPageElement(root, ".nav");
  const hero = root.querySelector(".hero") || root.firstElementChild;
  const banner = getPageElement(root, ".scrolling_banner.main");
  const close = banner?.querySelector(".close_ticker");
  if (banner && bannerDismissed) banner.style.display = "none";
  const readScroll = () => Math.max(0, Math.min(
    window.innerWidth < 991 ? window.scrollY : (lenis?.scroll ?? window.scrollY),
    Math.max(0, document.documentElement.scrollHeight - window.innerHeight),
  ));
  let previousScroll = readScroll();
  let revealProgress = retainedGradientProgress;
  const update = () => {
    if (!nav || !hero) return;
    const scroll = readScroll();
    const distance = Math.max(window.innerHeight * 0.2, 1);
    revealProgress = Math.min(1, Math.max(0, revealProgress + (previousScroll - scroll) / distance));
    // Return to the clear header progressively as the page reaches the top.
    if (scroll !== previousScroll) revealProgress = Math.min(revealProgress, scroll / distance);
    previousScroll = scroll;
    nav.style.setProperty("--nav-gradient-opacity", revealProgress);
    nav.style.setProperty("--nav-gradient-y", `${-(100 + window.innerWidth * 0.02) * (1 - revealProgress)}px`);
  };
  const hide = (event) => {
    event.preventDefault();
    bannerDismissed = true;
    banner.style.display = "none";
  };
  close?.addEventListener("click", hide);
  window.addEventListener("scroll", update, { passive: true });
  window.addEventListener("resize", update);
  lenis?.on?.("scroll", update);
  update();
  return () => {
    retainedGradientProgress = revealProgress;
    close?.removeEventListener("click", hide);
    window.removeEventListener("scroll", update);
    window.removeEventListener("resize", update);
    lenis?.off?.("scroll", update);
  };
}
