import { initBarba } from "./modules/barba.js";
import { installUnderlineLinkStyles } from "./modules/text-animations.js";
import { initThreeScene } from "./modules/three-scene.js";
import { destroyLinkHover, initLinkHover } from "./modules/link-hover.js";
import { destroyLogoJitter, initLogoJitter } from "./modules/logo-jitter.js";
import { destroyScrollingBanner, initScrollingBanner } from "./modules/scrolling-banner.js";
import { startLenisRaf } from "./modules/lenis-raf.js";
import { destroySectionNavigation, initSectionNavigation } from "./modules/section-navigation.js";
import { destroySectionParallax, initSectionParallax } from "./modules/section-parallax.js";
import { hideFloatingRegister, initFloatingRegister, prepareFloatingRegister } from "./modules/floating-register.js";
import { domReady } from "./utils/dom-ready.js";
import { initShopPageUi } from "./modules/shop-page-ui.js";
import { getPageElement, syncPageShell } from "./modules/page-shell.js";
import { initHeroScroll } from "./modules/hero-scroll.js";
import { initHeaderScroll } from "./modules/header-scroll.js";
import { initProductHover } from "./modules/product-hover.js";
import { initProductFilters } from "./modules/product-filters.js";
import { destroyMagazineLayout, initMagazineLayout } from "./modules/magazine-layout.js";
import { initAccordions } from "./modules/accordions.js";
import { initPlayVideo } from "./modules/play-video.js";
import { initFormSubmitReveal, initMobileRegister } from "./modules/form-submit-reveal.js";
import { initAgeGate } from "./modules/age-gate.js";
import { initPromoPopup } from "./modules/promo-popup.js";
import { populateProductPrices, preparePaymentButtons } from "./modules/shopify-cart.js";
import { resetPageScroll } from "./modules/scroll-reset.js";
import { initLogoLottieControls, destroyLogoLottieControls } from "./modules/logo-lottie-controls.js";

const app = { three: null, barba: null, lenis: null };
const pageStates = new WeakMap();
const DIAGNOSTIC_FLAGS = new URLSearchParams(window.location.search);
const ENABLE_LOGO_JITTER = !DIAGNOSTIC_FLAGS.has("nojitter");
const DISABLE_THREE_FOR_DIAGNOSTICS = DIAGNOSTIC_FLAGS.has("no3d");
const DISABLE_LOGO_JSON_FOR_DIAGNOSTICS = DIAGNOSTIC_FLAGS.has("nojson");
const SAFARI_STATIC_LOGO = isSafari();
installUnderlineLinkStyles();
installNavCurrentStyles();
initAgeGate();
initPromoPopup();
prepareLogoHost(document);
if (SAFARI_STATIC_LOGO) installStaticLogo(document);

function isSafari() {
  const userAgent = navigator.userAgent;
  return /Safari/i.test(userAgent) && !/(Chrome|Chromium|CriOS|Edg|EdgiOS|OPR|FxiOS|Firefox)/i.test(userAgent);
}

function prepareLogoHost(root) {
  root.querySelectorAll?.(".hero_logo").forEach((container) => {
    if (container.matches(".main") && container.tagName === "A") {
      const host = document.createElement("div");
      for (const attribute of container.attributes) {
        if (!["href", "target", "rel", "role", "tabindex", "aria-label"].includes(attribute.name)) {
          host.setAttribute(attribute.name, attribute.value);
        }
      }
      host.append(...container.childNodes);
      container.replaceWith(host);
      container = host;
    }
    if (container.dataset.src) container.dataset.logoSource = container.dataset.src;
    container.removeAttribute("data-animation-type");
    container.removeAttribute("data-w-id");
    container.removeAttribute("data-src");
  });
}

function installStaticLogo(root) {
  root.querySelectorAll?.(".hero_logo").forEach((container) => {
    if (container.querySelector("img[data-static-hero-logo]")) return;
    const image = document.createElement("img");
    const namespace = container.closest("[data-barba='container']")?.dataset.barbaNamespace?.toLowerCase();
    image.src = namespace !== "capsule 02" && namespace !== "capsule02"
      ? (container.dataset.staticLogo || "https://cdn.jsdelivr.net/gh/kujira22/other-label-texture@e5ee17167fdaa5e08d7c2ba38c38dff6cdb8a4d3/hero-logo-main.svg")
      : "https://cdn.jsdelivr.net/gh/kujira22/other-label-texture@8ad5291/hero-logo.svg";
    image.alt = "";
    image.setAttribute("aria-hidden", "true");
    image.dataset.staticHeroLogo = "";
    image.draggable = false;
    image.style.cssText = "display:block;width:100%;height:100%;object-fit:contain;pointer-events:none";
    image.addEventListener("error", () => console.warn("[logo] Static logo could not be loaded:", image.src), { once: true });
    container.replaceChildren(image);
  });
}

function installNavCurrentStyles() {
  const style = document.createElement("style");
  style.textContent = `
    .nav_holder { z-index: 1000; }
    .nav_holder, .nav_group, .nav, [data-section-navigation] { pointer-events: none; }
    .nav_holder a, .nav_holder button, .nav_holder input,
    .nav a, .nav button, [data-section-navigation] a,
    [data-section-navigation] button, .nav_holder [role="button"],
    .nav_holder [data-cart-btn] { pointer-events: auto; }
    .hero_logo.main { pointer-events: none; }
    .hero.home { pointer-events: none; }
    .hero.home > * { pointer-events: auto; }
    .nav, [data-section-navigation] { isolation: isolate; }
    .nav::before, [data-section-navigation]::before {
      content: "";
      position: fixed;
      inset: 0 0 auto;
      height: 180px;
      z-index: -1;
      pointer-events: none;
      display: var(--nav-gradient-display, none);
      opacity: var(--nav-gradient-opacity, 0);
      background: linear-gradient(to bottom, rgb(var(--nav-gradient-rgb, 237, 255, 0)) 0%, rgba(var(--nav-gradient-rgb, 237, 255, 0), 0.82) 38%, rgba(var(--nav-gradient-rgb, 237, 255, 0), 0) 100%);
      transform: translate3d(0, var(--nav-gradient-y, 0px), 0);
      will-change: transform, opacity;
    }
    .nav a.cta.w--current {
      background-color: var(--colour--other-blue);
      color: var(--colour--other-yellow);
    }
    body:not([data-page="capsule 02"]):not([data-page="capsule02"]) .nav::before {
      height: calc(2vw + 100px);
      background: linear-gradient(to bottom, rgb(var(--nav-gradient-rgb)) 0, rgb(var(--nav-gradient-rgb)) 2vw, rgba(var(--nav-gradient-rgb), 0) 100%);
    }
    @media (width < 991px) {
      .nav::before, [data-section-navigation]::before {
        --nav-gradient-overscan: calc(160px + env(safe-area-inset-top, 0px));
        top: calc(-1 * var(--nav-gradient-overscan));
        height: calc(var(--nav-gradient-overscan) + 2vw + 100px) !important;
        opacity: 1 !important;
        transform: none !important;
        will-change: auto;
        background: linear-gradient(to bottom,
          rgb(var(--nav-gradient-rgb, 237, 255, 0)) 0,
          rgb(var(--nav-gradient-rgb, 237, 255, 0)) calc(var(--nav-gradient-overscan) + 2vw),
          rgba(var(--nav-gradient-rgb, 237, 255, 0), 0) 100%) !important;
      }
    }
  `;
  document.head.appendChild(style);
}

async function boot() {
  await domReady();
  await window.lenisReady;
  app.lenis = window.lenis || (typeof lenis !== "undefined" ? lenis : null);
  const userAgent = navigator.userAgent;
  const isTouchViewport = window.matchMedia("(hover: none), (pointer: coarse)").matches
    || /Android|iPhone|iPad|iPod/i.test(userAgent)
    || (navigator.maxTouchPoints > 1 && /Macintosh/i.test(userAgent));
  if (isTouchViewport) window.ScrollTrigger?.config({ ignoreMobileResize: true });
  const htmlRunsLenis = [...document.scripts].some((script) => !script.src && /\blenis\.raf\s*\(/.test(script.textContent));
  if (!htmlRunsLenis) startLenisRaf(app.lenis);
  if (DISABLE_THREE_FOR_DIAGNOSTICS) console.info("[diagnostics] Three.js scene disabled by ?no3d=1");
  app.barba = initBarba({
    onEnter: runPageSetup,
    onLeave: runPageTeardown,
    onBeforeLeave: ({ container }) => {
      hideFloatingRegister(container);
      destroySectionNavigation();
      pageStates.get(container)?.destroyShopPageUi?.();
      pageStates.get(container)?.destroyHeaderScroll?.({ preserveState: true });
      if (pageStates.has(container)) pageStates.get(container).destroyHeaderScroll = null;
      window.ScrollTrigger?.getAll().forEach((trigger) => {
        if (trigger.trigger && (trigger.trigger === container || container.contains(trigger.trigger))) trigger.disable(false);
      });
    },
    onTransitionStart: () => {
      app.lenis?.stop();
    },
    onScrollReset: () => resetPageScroll(app.lenis),
    onTransitionReveal: ({ container }) => {
      pageStates.get(container)?.destroyHeaderScroll?.reveal?.();
    },
    onTransitionComplete: () => {
      resetPageScroll(app.lenis);
      app.lenis?.start();
      app.three?.syncScroll();
    },
  });

  if (!app.barba) {
    const container = document.querySelector("[data-barba='container']");
    await runPageSetup({ container });
  }
}

async function runPageSetup({ container, namespace, html, transition = false }) {
  if (!container) return;
  if (transition) {
    resetPageScroll(app.lenis);
  }
  const pageNamespace = String(namespace || container.dataset.barbaNamespace || "page").toLowerCase();
  const isCapsule = pageNamespace === "capsule 02" || pageNamespace === "capsule02";
  const setup = async () => {
    const state = {};
    pageStates.set(container, state);
    container.dataset.pageActive = "true";
    document.body.dataset.page = pageNamespace;
    const Webflow = window.Webflow;
    Webflow?.destroy?.();
    prepareLogoHost(container);
    if (SAFARI_STATIC_LOGO) installStaticLogo(container);
    const incoming = html ? new DOMParser().parseFromString(html, "text/html") : document;
    destroyMagazineLayout();
    syncPageShell(container, incoming, (element) => {
      if (element.matches(".scrolling_banner")) destroyScrollingBanner(element);
    });
    if (html) {
      const pageId = incoming.documentElement.getAttribute("data-wf-page");
      if (pageId) document.documentElement.setAttribute("data-wf-page", pageId);
    }
    syncNavCurrent(incoming);
    initMagazineLayout(container);
    const gradientColours = {
      yellow: "237, 255, 0", pink: "255, 210, 249", red: "255, 60, 0",
      blue: "0, 0, 106", white: "255, 255, 255",
    };
    const gradientName = container.dataset.gradColour?.trim().toLowerCase();
    const gradientColour = gradientColours[gradientName];
    document.querySelectorAll(".nav, [data-section-navigation]").forEach((nav) => {
      nav.style.setProperty("--nav-gradient-display", gradientColour ? "block" : "none");
      if (gradientColour) nav.style.setProperty("--nav-gradient-rgb", gradientColour);
      else nav.style.removeProperty("--nav-gradient-rgb");
    });
    if (isCapsule) {
      initScrollingBanner(document, app.lenis);
      initSectionNavigation({
      nav: getPageElement(container, ".nav, [data-section-navigation]"),
      sectionsRoot: container,
      ticker: getPageElement(container, ".scrolling_banner"),
      lenis: app.lenis,
      });
    } else {
      initScrollingBanner(container, app.lenis, ".press_ticker_holder");
      state.destroyShopPageUi = initShopPageUi({ root: container, lenis: app.lenis });
      state.destroyHeaderScroll = initHeaderScroll(container, app.lenis);
    }
    initSectionParallax({ root: container, lenis: app.lenis });
    prepareFloatingRegister(container);
    Webflow?.ready?.();
    Webflow?.require?.("ix2")?.init?.();
    initLinkHover(container);
    state.destroyProductHover = initProductHover(container);
    state.destroyProductFilters = initProductFilters(container);
    state.destroyAccordions = initAccordions(container);
    state.destroyVideos = initPlayVideo(container);
    state.destroyFormSubmitReveal = initFormSubmitReveal(container);
    state.destroyMobileRegister = initMobileRegister(container);
    initFloatingRegister(container, { register: isCapsule });
    preparePaymentButtons(container);
    void populateProductPrices(container);
    if (!SAFARI_STATIC_LOGO && !DISABLE_LOGO_JSON_FOR_DIAGNOSTICS) {
      try {
        await initLogoLottieControls(container, { playOnce: !isCapsule });
      } catch (error) {
        console.error("[logo] Animation unavailable; continuing page setup.", error);
      }
    } else if (DISABLE_LOGO_JSON_FOR_DIAGNOSTICS) {
      console.info("[diagnostics] Logo Lottie JSON disabled by ?nojson=1");
    }
    if (ENABLE_LOGO_JITTER && !SAFARI_STATIC_LOGO) initLogoJitter(container);
    if (!isCapsule) {
      state.destroyHeroScroll = initHeroScroll(container, app.lenis);
    }
    if (!DISABLE_THREE_FOR_DIAGNOSTICS) {
      state.three = initThreeScene({ mount: container.querySelector("[data-three-canvas]"), lenis: app.lenis });
    }
    app.three = state.three || null;
    app.three?.setPage({ capsule: isCapsule, scrollTarget: isCapsule ? container.querySelector("#origin") : null });
    const today = new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "long", year: "numeric" }).format(new Date());
    container.querySelectorAll("[data-todaysdate]").forEach((element) => { element.textContent = today; });
    container.querySelectorAll("[data-year]").forEach((element) => {
      element.textContent = String(new Date().getFullYear());
    });
  };

  await setup();
  if (!transition) window.ScrollTrigger?.refresh();
}

function syncNavCurrent(page) {
  const activeHref = page.querySelector(".nav a.w--current[href], [data-section-navigation] a.w--current[href]")?.getAttribute("href");
  document.querySelectorAll(".nav a[href], [data-section-navigation] a[href]").forEach((link) => {
    const active = Boolean(activeHref && link.getAttribute("href") === activeHref);
    link.classList.toggle("w--current", active);
    if (active) link.setAttribute("aria-current", "page");
    else link.removeAttribute("aria-current");
  });
}

function runPageTeardown({ container }) {
  if (!container || !container.dataset.pageActive) return;
  const state = pageStates.get(container);
  state?.three?.destroy();
  if (app.three === state?.three) app.three = null;
  destroySectionParallax(container);
  destroyScrollingBanner(container);
  state?.destroyShopPageUi?.();
  state?.destroyHeroScroll?.();
  state?.destroyHeaderScroll?.();
  state?.destroyProductHover?.();
  state?.destroyProductFilters?.();
  state?.destroyAccordions?.();
  state?.destroyVideos?.();
  state?.destroyFormSubmitReveal?.();
  state?.destroyMobileRegister?.();
  destroyLogoLottieControls(container);
  destroyLinkHover(container);
  destroyLogoJitter(container);
  delete container.dataset.pageActive;
  pageStates.delete(container);
}

boot().catch((error) => {
  console.error("[base] Setup failed.", error);
});

export { app };
