const DURATION = 0.8;
const LOG_PREFIX = "[base lifecycle]";
const TRANSITION_PROPERTIES = ["position", "top", "left", "width", "z-index", "pointer-events", "opacity", "transition"];

export function transition({ onEnter, onLeave, onBeforeLeave, onStart, onComplete, onReveal, onScrollReset } = {}) {
  let ready;
  let release;
  const originalStyles = new WeakMap();
  let scrollStyles;
  const resetScroll = () => {
    if (onScrollReset) onScrollReset();
    else window.scrollTo({ top: 0, left: 0, behavior: "instant" });
  };
  return {
    name: "transition",
    sync: true,
    async once({ next }) {
      console.log(LOG_PREFIX, "transition once -> run setup", getContainerContext(next));
      await onEnter?.(getPageContext(next));
    },
    async before({ current, next }) {
      console.log(LOG_PREFIX, "transition before", getTransitionContext(current, next));
      current.container.dataset.pageLeaving = "true";
      scrollStyles = ["scroll-behavior", "overflow-anchor"].map((property) => ({
        property, value: document.documentElement.style.getPropertyValue(property),
        priority: document.documentElement.style.getPropertyPriority(property),
      }));
      document.documentElement.style.setProperty("scroll-behavior", "auto", "important");
      document.documentElement.style.setProperty("overflow-anchor", "none", "important");
      if (current.container.contains(document.activeElement)) document.activeElement.blur?.();
      onStart?.(getPageContext(current));
      await onBeforeLeave?.(getPageContext(current));
      const scrollY = window.scrollY;
      for (const page of [current, next]) originalStyles.set(page.container, TRANSITION_PROPERTIES.map((property) => ({
        property, value: page.container.style.getPropertyValue(property), priority: page.container.style.getPropertyPriority(property),
      })));
      Object.assign(current.container.style, { position: "fixed", top: `${-scrollY}px`, left: "0", width: "100%", zIndex: "1", pointerEvents: "none" });
      Object.assign(next.container.style, { position: "fixed", top: "0", left: "0", width: "100%", zIndex: "2", opacity: "0", pointerEvents: "none" });
      resetScroll();
      ready = new Promise((resolve) => { release = resolve; });
    },
    async leave({ current }) {
      await ready;
      await fade(current.container, 0);
    },
    async enter({ next }) {
      delete next.container.dataset.pageLeaving;
      try {
        await onEnter?.(getPageContext(next, { transition: true }));
        await document.fonts?.ready;
        await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
        resetScroll();
      } finally {
        release();
      }
      onReveal?.(getPageContext(next));
      await fade(next.container, 1);
    },
    async after({ current, next }) {
      await onLeave?.(getPageContext(current));
      for (const page of [current, next]) {
        for (const { property, value, priority } of originalStyles.get(page.container) || []) {
          if (value) page.container.style.setProperty(property, value, priority);
          else page.container.style.removeProperty(property);
        }
        delete page.container.dataset.pageLeaving;
      }
      resetScroll();
      window.ScrollTrigger?.refresh();
      await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
      resetScroll();
      onComplete?.(getPageContext(next));
      for (const { property, value, priority } of scrollStyles || []) {
        if (value) document.documentElement.style.setProperty(property, value, priority);
        else document.documentElement.style.removeProperty(property);
      }
    },
  };
}

function fade(container, opacity) {
  const gsap = window.gsap;
  if (gsap) {
    return gsap.to(container, {
      opacity,
      duration: DURATION,
      ease: "power1.inOut",
      overwrite: true,
    });
  }

  return new Promise((resolve) => {
    container.style.transition = `opacity ${DURATION}s ease-in-out`;
    requestAnimationFrame(() => {
      container.style.opacity = String(opacity);
      window.setTimeout(resolve, DURATION * 1000);
    });
  });
}

function getTransitionContext(current, next) {
  return { current: getContainerContext(current), next: getContainerContext(next) };
}

function getContainerContext(page) {
  return {
    namespace: getNamespaceFromPage(page),
    connected: Boolean(page?.container?.isConnected),
    className: page?.container?.className || "",
  };
}

function getPageContext(page, options = {}) {
  return {
    container: page?.container || null,
    html: page?.html,
    namespace: getNamespaceFromPage(page),
    transition: Boolean(options.transition),
  };
}

function getNamespaceFromPage(page) {
  return String(page?.namespace || page?.container?.dataset?.barbaNamespace || "page")
    .trim()
    .toLowerCase();
}
