let nextAnswerId = 0;

export function initAccordions(root) {
  const cleanups = [];
  root.querySelectorAll("[data-question]:not(.answer)").forEach((question) => {
    const answer = question.nextElementSibling;
    if (!answer?.matches("[data-answer], .answer")) return;
    const attributes = ["role", "tabindex", "aria-expanded", "aria-controls"];
    const previous = attributes.map((name) => question.getAttribute(name));
    const originalStyle = answer.getAttribute("style");
    const originalId = answer.getAttribute("id");
    const wasHidden = answer.hidden;
    const marker = [...question.children].find((child) => child.textContent.trim() === "+");
    const display = getComputedStyle(answer).display;
    const openDisplay = display === "none" ? (answer.classList.contains("flex") ? "flex" : "block") : display;
    if (!answer.id) answer.id = `product-answer-${++nextAnswerId}`;
    question.setAttribute("aria-controls", answer.id);
    if (!question.matches("button, a[href]")) {
      question.setAttribute("role", "button");
      question.setAttribute("tabindex", "0");
    }
    const setOpen = (open) => {
      question.setAttribute("aria-expanded", String(open));
      answer.hidden = !open;
      answer.style.display = open ? openDisplay : "none";
      if (marker) marker.textContent = open ? "-" : "+";
    };
    const toggle = (event) => {
      event.preventDefault();
      setOpen(question.getAttribute("aria-expanded") !== "true");
      window.ScrollTrigger?.refresh();
    };
    const onKey = (event) => {
      if (question.matches("button")) return;
      if (event.key === " " || (event.key === "Enter" && !question.matches("a[href]"))) toggle(event);
    };
    setOpen(false);
    question.addEventListener("click", toggle);
    question.addEventListener("keydown", onKey);
    cleanups.push(() => {
      question.removeEventListener("click", toggle);
      question.removeEventListener("keydown", onKey);
      attributes.forEach((name, i) => previous[i] === null ? question.removeAttribute(name) : question.setAttribute(name, previous[i]));
      if (originalStyle === null) answer.removeAttribute("style");
      else answer.setAttribute("style", originalStyle);
      if (originalId === null) answer.removeAttribute("id");
      answer.hidden = wasHidden;
      if (marker) marker.textContent = "+";
    });
  });
  return () => cleanups.forEach((cleanup) => cleanup());
}
