import * as THREE from "three";
import { ImprovedNoise } from "three/examples/jsm/math/ImprovedNoise.js";

export const CHAMPAGNE_DEFAULTS = { scale: 1.27, rotationX: 0, rotationY: -108, rotationZ: 0, yOffset: -0.03 };

function createCorkGrain() {
  const size = 512;
  const pixels = new Uint8Array(size * size * 4);
  const relief = new Uint8Array(pixels.length);
  const noise = new ImprovedNoise();
  const cells = 18;
  const hash = (x, y, seed = 0) => {
    const value = Math.sin(((x % cells + cells) % cells) * 127.1 + ((y % cells + cells) % cells) * 311.7 + seed * 74.7) * 43758.5453;
    return value - Math.floor(value);
  };
  // Sample a torus so both texture edges join without a visible seam.
  for (let y = 0; y < size; y++) {
    const v = y / size * Math.PI * 2;
    for (let x = 0; x < size; x++) {
      const u = x / size * Math.PI * 2;
      const nx = (4 + Math.cos(v)) * Math.cos(u);
      const ny = (4 + Math.cos(v)) * Math.sin(u);
      const nz = Math.sin(v);
      // Uneven compressed fragments, rather than a uniform sand-like noise.
      const warp = noise.noise(nx * 2, ny * 2, nz * 2);
      const px = x / size * cells + warp * 0.35;
      const py = y / size * cells + noise.noise(nx * 2 + 9, ny * 2, nz * 2) * 0.35;
      let nearest = Infinity, second = Infinity, fragment = 0;
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          const cx = Math.floor(px) + dx, cy = Math.floor(py) + dy;
          const distance = Math.hypot(cx + hash(cx, cy) - px, cy + hash(cx, cy, 1) - py);
          if (distance < nearest) {
            second = nearest;
            nearest = distance;
            fragment = hash(cx, cy, 2);
          } else if (distance < second) second = distance;
        }
      }
      const fine = noise.noise(nx * 32, ny * 32, nz * 32);
      const grain = noise.noise(nx * 10, ny * 10, nz * 10);
      const seam = 1 - THREE.MathUtils.smoothstep(second - nearest, 0.005, 0.065);
      const pore = THREE.MathUtils.smoothstep(-grain, 0.28, 0.58);
      const shade = THREE.MathUtils.clamp(0.72 + fragment * 0.27 + warp * 0.12 + fine * 0.08 - seam * 0.12 - pore * 0.36, 0.25, 1);
      const height = THREE.MathUtils.clamp(0.58 + fragment * 0.08 + fine * 0.08 - seam * 0.08 - pore * 0.35, 0, 1);
      const offset = (y * size + x) * 4;
      pixels[offset] = Math.round(shade * 255);
      pixels[offset + 1] = Math.round(shade * (0.96 + fragment * 0.04) * 255);
      pixels[offset + 2] = Math.round(shade * (0.89 + fragment * 0.11) * 255);
      relief[offset] = relief[offset + 1] = relief[offset + 2] = Math.round(height * 255);
      pixels[offset + 3] = relief[offset + 3] = 255;
    }
  }
  const textures = [pixels, relief].map((data) => {
    const texture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
    texture.name = "Generated cork fragments";
    texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearMipmapLinearFilter;
    texture.generateMipmaps = true;
    texture.needsUpdate = true;
    return texture;
  });
  return { colour: textures[0], bump: textures[1] };
}

export function createChampagneCork(source, reference) {
  source.updateMatrixWorld(true);
  const cork = source.getObjectByName("CORK");
  if (!cork?.isMesh) throw new Error("Champagne GLB is missing its CORK mesh");
  const bounds = new THREE.Box3().setFromObject(cork);
  const size = bounds.getSize(new THREE.Vector3());
  const center = bounds.getCenter(new THREE.Vector3());
  const stem = new THREE.Box3();
  const point = new THREE.Vector3();
  const positions = cork.geometry.getAttribute("position");
  for (let index = 0; index < positions.count; index++) {
    point.fromBufferAttribute(positions, index).applyMatrix4(cork.matrixWorld);
    if (point.y < bounds.min.y + size.y * 0.25) stem.expandByPoint(point);
  }
  const stemSize = stem.getSize(new THREE.Vector3());
  const scale = reference.scale.x / Math.max(stemSize.x, stemSize.z);
  if (!Number.isFinite(scale) || scale <= 0) throw new Error("Invalid champagne cork dimensions");

  // Approximate the stem/shoulder junction at the mouth; the GUI offset fine-tunes seating.
  const seatingY = bounds.min.y + size.y * 0.5;
  const content = new THREE.Group();
  content.add(source);
  source.position.sub(new THREE.Vector3(center.x, seatingY, center.z));
  content.scale.setScalar(scale);
  const assembly = new THREE.Group();
  assembly.name = "Champagne cork and cage";
  assembly.add(content);
  const mouthY = reference.position.y + reference.scale.y / 2;
  assembly.position.set(reference.position.x, mouthY + CHAMPAGNE_DEFAULTS.yOffset, reference.position.z);
  assembly.scale.setScalar(CHAMPAGNE_DEFAULTS.scale);
  assembly.rotation.set(...[CHAMPAGNE_DEFAULTS.rotationX, CHAMPAGNE_DEFAULTS.rotationY, CHAMPAGNE_DEFAULTS.rotationZ].map(THREE.MathUtils.degToRad));

  const grain = createCorkGrain();
  const materials = {
    Cork: new THREE.MeshStandardMaterial({ name: "Champagne cork", color: "#916b40", map: grain.colour, bumpMap: grain.bump, bumpScale: 0.001, roughness: 0.95, metalness: 0 }),
    Cap: new THREE.MeshStandardMaterial({ name: "Champagne cap", color: "#343432", roughness: 0.28, metalness: 1 }),
    Cage: new THREE.MeshStandardMaterial({ name: "Champagne cage", color: "#a18212", roughness: 0.05, metalness: 1 }),
  };
  const replaced = new Set();
  source.traverse((mesh) => {
    if (!mesh.isMesh) return;
    const material = mesh.name === "CORK" ? materials.Cork
      : mesh.name === "CAP" ? materials.Cap
        : ["WIRE-CAGE", "WIRE-SEAL"].includes(mesh.name) ? materials.Cage : null;
    if (!material) return;
    (Array.isArray(mesh.material) ? mesh.material : [mesh.material]).forEach((entry) => replaced.add(entry));
    mesh.material = material;
  });
  replaced.forEach((material) => material.dispose());

  return {
    mesh: assembly,
    materials,
    setScale: (value) => { assembly.scale.setScalar(value); },
    setRotation: (x, y, z) => {
      assembly.rotation.set(...[x, y, z].map(THREE.MathUtils.degToRad));
    },
    setYOffset: (value) => { assembly.position.y = mouthY + value; },
  };
}
