const COOKIE_NAME = "other_age_confirmed";

export function initAgeGate() {
  const style = document.createElement("style");
  style.textContent = `
    html:not(.age-confirmed) .age_gate { display: flex !important; }
    html.age-confirmed .age_gate { display: none !important; }
    @media (width < 991px) {
      .age_gate {
        inset: 0 !important;
        height: auto !important;
        min-height: 100dvh;
        overflow-y: auto;
        overscroll-behavior: contain;
        box-sizing: border-box;
        z-index: 2000;
      }
      html:not(.age-confirmed), html:not(.age-confirmed) body { overflow: hidden; }
    }
  `;
  document.head.appendChild(style);

  const confirmed = document.cookie.split(";").some((cookie) => cookie.trim() === `${COOKIE_NAME}=yes`);
  document.documentElement.classList.toggle("age-confirmed", confirmed);

  document.addEventListener("click", (event) => {
    const button = event.target.closest?.('.age_gate [data-age="yes"]');
    if (!button) return;
    event.preventDefault();
    // No expiry: confirmation lasts for the browser session only.
    document.cookie = `${COOKIE_NAME}=yes; Path=/; SameSite=Lax${location.protocol === "https:" ? "; Secure" : ""}`;
    document.documentElement.classList.add("age-confirmed");
    document.dispatchEvent(new Event("age-confirmed"));
  });
}
