import { getPageElement } from "./page-shell.js";

let pendingOffsets = null;

export function headerOffset(offset, delta, scroll, hidden, revealed) {
  if (scroll <= 0) return 0;
  if (delta > 0) return Math.max(hidden, offset - delta);
  if (delta < 0) return Math.min(Math.max(revealed, -scroll), offset - delta);
  return offset;
}

export function initHeaderScroll(root, lenis) {
  const logo = root.querySelector(".hero_logo.main");
  const nav = getPageElement(root, ".nav_holder");
  if (!logo || !nav) return () => {};

  const incomingOffsets = pendingOffsets;
  pendingOffsets = null;
  const items = [logo, nav].map((element, index) => ({
    element, y: index === 0 ? (incomingOffsets?.[index] ?? 0) : 0, hidden: 0, revealed: 0,
    translate: element.style.getPropertyValue("translate"),
    priority: element.style.getPropertyPriority("translate"),
  }));
  const readScroll = () => Math.max(0, Math.min(
    window.innerWidth < 991 ? window.scrollY : (lenis?.scroll ?? window.scrollY),
    Math.max(0, document.documentElement.scrollHeight - window.innerHeight),
  ));
  let previous = readScroll();
  let measured = false;
  let revealTween;
  let viewportWidth = window.innerWidth;
  function render() {
    items.forEach(({ element, y }) => {
      element.style.setProperty("translate", `0 ${y}px`);
    });
    logo.dispatchEvent(new Event("logo-frame-change"));
  }
  function measure() {
    if (window.innerWidth < 991) {
      items.forEach((item) => { item.y = 0; });
      previous = readScroll();
      measured = true;
      render();
      return;
    }
    items.forEach((item) => {
      item.element.style.setProperty("translate", "none");
      const rect = item.element.getBoundingClientRect();
      item.hidden = -Math.max(0, rect.bottom);
      item.revealed = 0;
      if (!measured && !incomingOffsets) item.y = Math.max(item.hidden, -previous);
      else if (rect.height > 0) item.y = Math.max(item.hidden, Math.min(0, item.y));
    });
    measured = true;
    render();
  }
  function update() {
    const scroll = readScroll();
    if (window.innerWidth < 991) {
      previous = scroll;
      return;
    }
    const delta = scroll - previous;
    if (!delta) return;
    revealTween?.kill();
    items.forEach((item) => {
      item.y = headerOffset(item.y, delta, scroll, item.hidden, item.revealed);
    });
    previous = scroll;
    render();
  }
  const onNativeScroll = () => {
    if (window.innerWidth < 991 || !lenis?.on) update();
  };
  const onLenisScroll = () => { if (window.innerWidth >= 991) update(); };
  const onResize = () => {
    if (window.innerWidth >= 991 || window.innerWidth !== viewportWidth) measure();
    viewportWidth = window.innerWidth;
  };
  measure();
  const observer = new ResizeObserver(measure);
  items.forEach(({ element }) => observer.observe(element));
  window.addEventListener("resize", onResize);
  // Listen to the rendered Lenis position, not its wheel target or a second eased value.
  lenis?.on?.("scroll", onLenisScroll);
  window.addEventListener("scroll", onNativeScroll, { passive: true });
  const destroy = ({ preserveState = false } = {}) => {
    revealTween?.kill();
    if (preserveState) pendingOffsets = items.map(({ y }) => y);
    observer.disconnect();
    window.removeEventListener("resize", onResize);
    lenis?.off?.("scroll", onLenisScroll);
    window.removeEventListener("scroll", onNativeScroll);
    if (!preserveState) items.forEach(({ element, translate, priority }) => {
      if (translate) element.style.setProperty("translate", translate, priority);
      else element.style.removeProperty("translate");
    });
  };
  destroy.reveal = () => {
    if (readScroll() > 0) return;
    revealTween?.kill();
    previous = readScroll();
    if (window.innerWidth < 991 || !window.gsap || window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      items.forEach((item) => { item.y = 0; });
      render();
      return;
    }
    revealTween = window.gsap.to(items[0], {
      y: 0, duration: 0.8, ease: "power1.inOut", onUpdate: render,
    });
  };
  return destroy;
}
